IF X2 THEN
    bFault := TRUE;
    bRun := FALSE;
    nStep := 0;
END_IF;
IF X1 THEN
    bFault := FALSE;
    bRun := FALSE;
    nStep := 0;
END_IF;
IF X0 AND NOT bX0Last AND NOT X1 AND NOT X2 AND NOT bFault THEN
    bRun := TRUE;
    nStep := 1;
END_IF;
bX0Last := X0;
tStep(IN := bRun AND NOT bFault, PT := STEP_TIMEOUT);
IF tStep.Q THEN
    bFault := TRUE;
    bRun := FALSE;
    nStep := 0;
END_IF;
IF bRun AND NOT bFault THEN
    CASE nStep OF
        1:
            IF X10 THEN
                nStep := 2;
            END_IF;
        2:
            IF X11 THEN
                nStep := 3;
            END_IF;
        3:
            IF X12 THEN
                nStep := 4;
            END_IF;
        4:
            IF X13 THEN
                nStep := 5;
            END_IF;
        5:
            IF X10 THEN
                nStep := 6;
            END_IF;
        6:
            IF X15 THEN
                nStep := 7;
            END_IF;
        7:
            IF X12 THEN
                nStep := 8;
            END_IF;
        8:
            IF X14 THEN
                nStep := 0;
                bRun := FALSE;
            END_IF;
    END_CASE;
END_IF;
Y0 := FALSE;
Y1 := FALSE;
Y2 := FALSE;
Y3 := FALSE;
Y4 := FALSE;
Y5 := bFault;
IF bRun AND NOT bFault THEN
    CASE nStep OF
        1:
            Y0 := TRUE;
        2:
            Y0 := TRUE;
            Y2 := TRUE;
        3:
            Y1 := TRUE;
            Y2 := TRUE;
        4:
            Y2 := TRUE;
