            Y2 := TRUE;
            Y3 := TRUE;
        6:
            Y0 := TRUE;
            Y3 := TRUE;
        7:
            Y1 := TRUE;
            Y3 := TRUE;
        8:
            Y4 := TRUE;
    END_CASE;
END_IF;
